import { Pool } from 'pg';

const connectionString = 'postgresql://neondb_owner:npg_JKfVe1Scpz7R@ep-proud-resonance-afmhcyuk-pooler.c-2.us-west-2.aws.neon.tech/neondb?sslmode=require&channel_binding=require';

export const pool = new Pool({
  connectionString,
  ssl: {
    rejectUnauthorized: false
  }
});

export async function initializeDatabase() {
  try {
    console.log('Connecting to PostgreSQL...');

    // Test connection
    const client = await pool.connect();
    console.log('Connected to PostgreSQL successfully');
    client.release();

    // Create tables if they don't exist
    await createTables();
    await insertSampleData();

    console.log('Database initialized successfully');
  } catch (error) {
    console.error('Database initialization error:', error);
    throw error;
  }
}

async function createTables() {
  // Add training_type column to member_profiles if it doesn't exist
  try {
    await pool.query(`
      ALTER TABLE member_profiles 
      ADD COLUMN IF NOT EXISTS training_type VARCHAR(20) DEFAULT 'one_on_one'
    `);
  } catch (error) {
    console.log('Column training_type might already exist or table not created yet');
  }

  // Add new columns to subscriptions table if they don't exist
  try {
    await pool.query(`
      ALTER TABLE subscriptions 
      ADD COLUMN IF NOT EXISTS plan_type VARCHAR(20) DEFAULT '12_session',
      ADD COLUMN IF NOT EXISTS training_type VARCHAR(20) DEFAULT 'one_on_one',
      ADD COLUMN IF NOT EXISTS sessions_total INTEGER DEFAULT 12,
      ADD COLUMN IF NOT EXISTS sessions_used INTEGER DEFAULT 0,
      ADD COLUMN IF NOT EXISTS price_paid DECIMAL(10,2),
      ADD COLUMN IF NOT EXISTS updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    `);
  } catch (error) {
    console.log('Subscription columns might already exist or table not created yet');
  }
  const createUsersTable = `
    CREATE TABLE IF NOT EXISTS users (
      id SERIAL PRIMARY KEY,
      email VARCHAR(255) UNIQUE NOT NULL,
      first_name VARCHAR(255) NOT NULL,
      last_name VARCHAR(255) NOT NULL,
      user_type VARCHAR(50) NOT NULL DEFAULT 'member',
      phone VARCHAR(20),
      password_hash VARCHAR(255),
      stripe_subscription_id VARCHAR(255),
      created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
      updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    );
  `;

  const createMembershipTiersTable = `
    CREATE TABLE IF NOT EXISTS membership_tiers (
      id SERIAL PRIMARY KEY,
      name VARCHAR(255) NOT NULL,
      sessions INTEGER NOT NULL,
      duration VARCHAR(50) NOT NULL,
      one_on_one_price DECIMAL(10,2) NOT NULL,
      one_on_one_per_session DECIMAL(10,2) NOT NULL,
      two_people_price DECIMAL(10,2) NOT NULL,
      two_people_per_session DECIMAL(10,2) NOT NULL,
      three_people_price DECIMAL(10,2) NOT NULL,
      three_people_per_session DECIMAL(10,2) NOT NULL,
      tiers JSONB DEFAULT '[]',
      features TEXT[],
      description TEXT,
      created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    );
  `;

  const createMemberProfilesTable = `
    CREATE TABLE IF NOT EXISTS member_profiles (
      id SERIAL PRIMARY KEY,
      user_id INTEGER REFERENCES users(id) ON DELETE CASCADE,
      first_name VARCHAR(255) NOT NULL,
      last_name VARCHAR(255) NOT NULL,
      email VARCHAR(255) UNIQUE NOT NULL,
      phone VARCHAR(20),
      membership_tier_id INTEGER REFERENCES membership_tiers(id),
      fitness_goals TEXT,
      emergency_contact VARCHAR(255),
      tier_category VARCHAR(20),
      training_type VARCHAR(20) DEFAULT 'one_on_one',
      created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
      updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    );
  `;

  const createTrainerProfilesTable = `
    CREATE TABLE IF NOT EXISTS trainer_profiles (
      id SERIAL PRIMARY KEY,
      user_id INTEGER REFERENCES users(id) ON DELETE CASCADE,
      first_name VARCHAR(255) NOT NULL,
      last_name VARCHAR(255) NOT NULL,
      email VARCHAR(255) UNIQUE NOT NULL,
      phone VARCHAR(20),
      specializations TEXT[],
      hourly_rate DECIMAL(10,2) DEFAULT 75.00,
      experience_years INTEGER DEFAULT 2,
      certifications TEXT,
      bio TEXT,
      is_available BOOLEAN DEFAULT true,
      created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
      updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    );
  `;

  const createSubscriptionsTable = `
      CREATE TABLE IF NOT EXISTS subscriptions (
        id SERIAL PRIMARY KEY,
        member_id INTEGER REFERENCES member_profiles(id) ON DELETE CASCADE UNIQUE,
        membership_tier_id INTEGER REFERENCES membership_tiers(id),
        plan_type VARCHAR(50),
        training_type VARCHAR(50) DEFAULT 'one_on_one',
        sessions_total INTEGER DEFAULT 0,
        sessions_used INTEGER DEFAULT 0,
        price_paid DECIMAL(10,2) DEFAULT 0,
        start_date DATE NOT NULL,
        end_date DATE NOT NULL,
        is_active BOOLEAN DEFAULT true,
        auto_renew BOOLEAN DEFAULT true,
        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
        updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
      )
    `;

  const createTrainingSessionsTable = `
    CREATE TABLE IF NOT EXISTS training_sessions (
      id SERIAL PRIMARY KEY,
      member_id INTEGER REFERENCES member_profiles(id),
      trainer_id INTEGER REFERENCES trainer_profiles(id),
      session_type VARCHAR(255),
      scheduled_date DATE,
      scheduled_time TIME,
      duration INTEGER DEFAULT 60,
      status VARCHAR(50) DEFAULT 'scheduled',
      notes TEXT,
      created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    );
  `;

  const createWorkoutPlansTable = `
    CREATE TABLE IF NOT EXISTS workout_plans (
      id SERIAL PRIMARY KEY,
      member_id INTEGER REFERENCES member_profiles(id),
      trainer_id INTEGER REFERENCES trainer_profiles(id),
      plan_name VARCHAR(255) NOT NULL,
      description TEXT,
      duration INTEGER,
      exercises TEXT,
      created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    );
  `;

  const createNutritionPlansTable = `
    CREATE TABLE IF NOT EXISTS nutrition_plans (
      id SERIAL PRIMARY KEY,
      member_id INTEGER REFERENCES member_profiles(id),
      trainer_id INTEGER REFERENCES trainer_profiles(id),
      plan_name VARCHAR(255) NOT NULL,
      description TEXT,
      calories INTEGER,
      meals TEXT,
      created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    );
  `;

  const createBodyAssessmentsTable = `
    CREATE TABLE IF NOT EXISTS body_assessments (
      id SERIAL PRIMARY KEY,
      member_id INTEGER REFERENCES member_profiles(id),
      trainer_id INTEGER REFERENCES trainer_profiles(id),
      client_name VARCHAR(255) NOT NULL,
      date_of_birth DATE,
      age INTEGER,
      height DECIMAL(5,2),
      bp VARCHAR(20),
      bp_after_treadmill VARCHAR(20),
      emergency_contact VARCHAR(255),
      bmi DECIMAL(5,2),
      weight DECIMAL(5,2),
      muscle DECIMAL(5,2),
      fat DECIMAL(5,2),
      saturated_fat DECIMAL(5,2),
      visceral_fat DECIMAL(5,2),
      bmr INTEGER,
      body_age INTEGER,
      postural_assessment TEXT,
      head_neck_alignment VARCHAR(255),
      shoulder_alignment VARCHAR(255),
      upper_back_alignment VARCHAR(255),
      lower_back_alignment VARCHAR(255),
      pelvic_alignment VARCHAR(255),
      hip_knee_alignment VARCHAR(255),
      ankle_alignment VARCHAR(255),
      spinal_mobility VARCHAR(255),
      recommendations TEXT,
      circumference_measurements JSONB,
      advice TEXT,
      created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    );
  `;

  const createAttendanceTable = `
    CREATE TABLE IF NOT EXISTS attendance (
      id SERIAL PRIMARY KEY,
      member_id INTEGER REFERENCES member_profiles(id),
      check_in_time TIMESTAMP NOT NULL,
      check_out_time TIMESTAMP,
      date DATE NOT NULL,
      created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    );
  `;

  const createTrainerAttendanceTable = `
    CREATE TABLE IF NOT EXISTS trainer_attendance (
      id SERIAL PRIMARY KEY,
      trainer_id INTEGER REFERENCES trainer_profiles(id) ON DELETE CASCADE,
      date DATE NOT NULL,
      status VARCHAR(20) NOT NULL DEFAULT 'present',
      check_in_time TIME,
      check_out_time TIME,
      notes TEXT,
      created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
      updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
      UNIQUE(trainer_id, date)
    );
  `;

  const createMemberSessionsTable = `
    CREATE TABLE IF NOT EXISTS member_sessions (
      id SERIAL PRIMARY KEY,
      member_id INTEGER REFERENCES member_profiles(id) ON DELETE CASCADE,
      trainer_id INTEGER REFERENCES trainer_profiles(id) ON DELETE CASCADE,
      session_type VARCHAR(255) NOT NULL,
      scheduled_date DATE NOT NULL,
      scheduled_time TIME NOT NULL,
      duration INTEGER DEFAULT 60,
      status VARCHAR(50) DEFAULT 'scheduled',
      notes TEXT,
      member_name VARCHAR(255),
      trainer_name VARCHAR(255),
      created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
      updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    );
  `;

  const createInquiriesTable = `
    CREATE TABLE IF NOT EXISTS inquiries (
      id SERIAL PRIMARY KEY,
      first_name VARCHAR(255) NOT NULL,
      last_name VARCHAR(255) NOT NULL,
      email VARCHAR(255) NOT NULL,
      phone VARCHAR(20),
      location VARCHAR(255),
      interest VARCHAR(255),
      message TEXT,
      status VARCHAR(50) DEFAULT 'new',
      created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
      updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    );
  `;

  const createMemberSessionAttendanceTable = `
    CREATE TABLE IF NOT EXISTS member_session_attendance (
      id SERIAL PRIMARY KEY,
      member_id INTEGER REFERENCES member_profiles(id) ON DELETE CASCADE,
      trainer_id INTEGER REFERENCES trainer_profiles(id) ON DELETE CASCADE,
      session_date DATE NOT NULL,
      session_time TIME,
      session_type VARCHAR(255),
      status VARCHAR(50) DEFAULT 'attended',
      notes TEXT,
      member_name VARCHAR(255),
      trainer_name VARCHAR(255),
      duration_minutes INTEGER DEFAULT 60,
      created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
      updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    );
  `;

  const createMemberTrainerAssignmentsTable = `
    CREATE TABLE IF NOT EXISTS member_trainer_assignments (
      id SERIAL PRIMARY KEY,
      member_id INTEGER REFERENCES member_profiles(id) ON DELETE CASCADE,
      trainer_id INTEGER REFERENCES trainer_profiles(id) ON DELETE CASCADE,
      assigned_date DATE DEFAULT CURRENT_DATE,
      is_active BOOLEAN DEFAULT true,
      notes TEXT,
      created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
      updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
      UNIQUE(member_id, trainer_id)
    );
  `;

  const createAuthTokensTable = `
    CREATE TABLE IF NOT EXISTS auth_tokens (
      id SERIAL PRIMARY KEY,
      user_id INTEGER REFERENCES users(id) ON DELETE CASCADE,
      token VARCHAR(255) UNIQUE NOT NULL,
      type VARCHAR(50) NOT NULL,
      new_email VARCHAR(255),
      expires_at TIMESTAMP NOT NULL,
      used BOOLEAN DEFAULT false,
      created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    );
  `;

  const tables = [
    createUsersTable,
    createMembershipTiersTable,
    createMemberProfilesTable,
    createTrainerProfilesTable,
    createSubscriptionsTable,
    createTrainingSessionsTable,
    createWorkoutPlansTable,
    createNutritionPlansTable,
    createBodyAssessmentsTable,
    createAttendanceTable,
    createTrainerAttendanceTable,
    createMemberSessionsTable,
    createInquiriesTable,
    createMemberSessionAttendanceTable,
    createMemberTrainerAssignmentsTable,
    createAuthTokensTable
  ];

  for (const table of tables) {
    await pool.query(table);
  }
}

async function insertSampleData() {
  try {
    // Check if table exists and has correct schema
    try {
      await pool.query('SELECT one_on_one_price FROM membership_tiers LIMIT 1');
    } catch (schemaError) {
      console.log('Schema issue detected, attempting to fix...');

      // Drop and recreate table if schema is wrong
      try {
        await pool.query('DROP TABLE IF EXISTS membership_tiers CASCADE');
        console.log('Dropped membership_tiers table');

        // Recreate the table
        const createMembershipTiersTable = `
          CREATE TABLE membership_tiers (
            id SERIAL PRIMARY KEY,
            name VARCHAR(255) NOT NULL,
            sessions INTEGER NOT NULL,
            duration VARCHAR(50) NOT NULL,
            one_on_one_price DECIMAL(10,2) NOT NULL,
            one_on_one_per_session DECIMAL(10,2) NOT NULL,
            two_people_price DECIMAL(10,2) NOT NULL,
