    <Switch>
      <Route path="/about" component={About} />
      <Route path="/services" component={Services} />
      <Route path="/contact" component={Contact} />
      <Route path="/login" component={Login} />
      <Route path="/subscribe" component={Subscribe} />
      <Route path="/membership" component={Subscribe} />
      <Route path="/forgot-password" component={ForgotPassword} />
      <Route path="/reset-password" component={ResetPassword} />
      <Route path="/confirm-email-change" component={ConfirmEmailChange} />

      {/* Dashboard routes - accessible when authenticated */}
      <Route path="/member-dashboard" component={MemberDashboard} />
      <Route path="/trainer-dashboard" component={TrainerDashboard} />
      <Route path="/admin-dashboard" component={AdminDashboard} />
      <Route path="/debug" component={DatabaseDebug} />

      {/* Home route - shows Landing page for unauthenticated users, Home for authenticated users */}
      <Route path="/">
        {!isAuthenticated ? <Landing /> : <Home />}
      </Route>

      <Route component={NotFound} />
    </Switch>
  );
}

function App() {
  return (
    <QueryClientProvider client={queryClient}>
      <TooltipProvider>
        <Toaster />
        <Router />
      </TooltipProvider>
    </QueryClientProvider>
  );
}

export default App;

