}

/* Enhanced modern animations */
.animate-fade-in {
  animation: fadeInUp 1.2s cubic-bezier(0.4, 0, 0.2, 1) forwards;
}

@keyframes fadeInUp {
  from {
    opacity: 0;
    transform: translateY(40px) scale(0.95);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

.animate-fade-in-delayed {
  animation: fadeInUp 1.2s cubic-bezier(0.4, 0, 0.2, 1) 0.3s both;
}

.animate-slide-in-left {
  animation: slideInLeft 1s cubic-bezier(0.4, 0, 0.2, 1) forwards;
}

@keyframes slideInLeft {
  from {
    opacity: 0;
    transform: translateX(-50px);
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}

.animate-slide-in-right {
  animation: slideInRight 1s cubic-bezier(0.4, 0, 0.2, 1) forwards;
}

@keyframes slideInRight {
  from {
    opacity: 0;
    transform: translateX(50px);
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}

/* Enhanced floating animation */
.animate-float {
  animation: smoothFloat 6s ease-in-out infinite;
}

@keyframes smoothFloat {
  0%, 100% {
    transform: translateY(0px) rotate(0deg) scale(1);
  }
  25% {
    transform: translateY(-10px) rotate(90deg) scale(1.05);
  }
  50% {
    transform: translateY(-20px) rotate(180deg) scale(1);
  }
  75% {
    transform: translateY(-10px) rotate(270deg) scale(1.05);
  }
}

/* Enhanced gradient text effect */
