.stagger-animation:nth-child(2) { animation-delay: 0.2s; }
.stagger-animation:nth-child(3) { animation-delay: 0.3s; }
.stagger-animation:nth-child(4) { animation-delay: 0.4s; }
.stagger-animation:nth-child(5) { animation-delay: 0.5s; }
.stagger-animation:nth-child(6) { animation-delay: 0.6s; }

/* Enhanced modern card hover effects */
.modern-card {
  position: relative;
  overflow: hidden;
  transition: all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
  transform-style: preserve-3d;
}

.modern-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: -100%;
  width: 100%;
  height: 100%;
  background: linear-gradient(90deg, 
    transparent, 
    rgba(255, 215, 0, 0.15), 
    rgba(255, 215, 0, 0.25),
    rgba(255, 215, 0, 0.15),
    transparent);
  transition: left 0.8s ease-out;
  z-index: 1;
}

.modern-card:hover::before {
  left: 100%;
}

.modern-card:hover {
  transform: translateY(-8px) rotateX(5deg);
  box-shadow: 
    0 20px 40px rgba(0, 0, 0, 0.3),
    0 10px 20px rgba(255, 215, 0, 0.1);
}

/* Interactive hover states */
.interactive-element {
  @apply transition-all duration-300 ease-out cursor-pointer;
}

.interactive-element:hover {
  @apply scale-105 brightness-110;
}

.interactive-element:active {
  @apply scale-95 brightness-90;
}

/* Magnetic button effect */
.magnetic-button {
  @apply relative transition-transform duration-200 ease-out;
}

.magnetic-button:hover {
  animation: magneticPulse 0.6s ease-out;
}

@keyframes magneticPulse {
  0% { transform: scale(1); }
  50% { transform: scale(1.05); }
  100% { transform: scale(1); }
}

/* Loading states enhancement */
.enhanced-loading {
  @apply relative overflow-hidden;
}

.enhanced-loading::before {
  content: '';
  @apply absolute inset-0 -translate-x-full bg-gradient-to-r 
         from-transparent via-white/10 to-transparent;
