import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { useQuery } from "@tanstack/react-query";
import { useLocation } from "wouter";
import { Check } from "lucide-react";

export default function MembershipTiers() {
  const [, setLocation] = useLocation();

  const { data: membershipTiers, isLoading, error } = useQuery({
    queryKey: ['membershipTiers'],
    queryFn: async () => {
      const response = await fetch('/api/membership-tiers');
      if (!response.ok) {
        throw new Error('Failed to fetch membership tiers');
      }
      return response.json();
    }
  });

  const handleSelectPlan = (tier: any, trainingType: string) => {
    const selectedPlan = {
      ...tier,
      trainingType,
      price: trainingType === 'one_on_one' ? tier.one_on_one_price :
             trainingType === 'two_people' ? tier.two_people_price :
             tier.three_people_price,
      perSessionRate: trainingType === 'one_on_one' ? tier.one_on_one_per_session :
                     trainingType === 'two_people' ? tier.two_people_per_session :
                     tier.three_people_per_session
    };
    localStorage.setItem('selectedTier', JSON.stringify(selectedPlan));
    setLocation('/subscribe');
  };

  if (isLoading) {
    return (
      <section className="py-24 bg-black">
        <div className="max-w-7xl mx-auto px-6 lg:px-8 text-center">
          <div className="animate-spin w-12 h-12 border-4 border-gold border-t-transparent rounded-full mx-auto"></div>
        </div>
      </section>
    );
  }

  if (error || !membershipTiers || !Array.isArray(membershipTiers)) {
    return (
      <section className="py-24 bg-black">
        <div className="max-w-7xl mx-auto px-6 lg:px-8 text-center">
          <p className="text-red-400">Failed to load membership tiers. Please try again later.</p>
        </div>
      </section>
