                      />
                    </div>
                    <Button
                      onClick={handleCreateNutritionPlan}
                      className="w-full bg-gold text-black hover:bg-white"
                    >
                      Create Plan
                    </Button>
                  </div>
                </DialogContent>
              </Dialog>

              {/* Edit Nutrition Plan Modal */}
              <Dialog open={showEditNutritionModal} onOpenChange={setShowEditNutritionModal}>
